$metaInput['metacategory_id'] = (int) $ai->term_id; $metaInput['title'] = 'Synthetic Meta Desktop';
$metaInput['client_uuid'] = wp_generate_uuid4(); $metaInput['publish'] = false; $metaInput['return_policy_id'] = 0;
