techCheck(is_wp_error(KREV_ListLab_Product_Writer::save($invalid, $savedMeta['id'])), 'a Google child cannot be submitted as a collection');
$invalid = $metaInput; $invalid['category_id'] = KREV_PA_Tech_Categories::root_id('art'); $invalid['subcategory_id'] = 0;
techCheck(is_wp_error(KREV_ListLab_Product_Writer::save($invalid, $savedMeta['id'])), 'cross-group collection rejected before mutation');
