$cleared = KREV_ListLab_Product_Writer::save($clear, $savedMeta['id']);
techCheck(!is_wp_error($cleared) && $cleared['metacategory_id'] === 0 && $cleared['subcategory_id'] === (int) $desktop->term_id, 'clearing a collection preserves its Google subcategory');
foreach (['iphones' => '267', 'laptops' => '328', 'mini-computers' => '5276'] as $slug => $googleId) {
    techCheck(in_array($googleId, KREV_PA_Metacategories::catalog()[$slug]['google_ids'], true), 'rollup includes the expected Google type: ' . $slug);
    techCheck(KREV_PA_Metacategories::matches($slug, [$googleId], '', $slug === 'iphones'), 'matching feed category rolls into ' . $slug);
}
techCheck(!KREV_PA_Metacategories::matches('iphones', ['267'], 'Samsung Galaxy', false), 'Android phones do not roll into iPhones');
techCheck(!KREV_PA_Metacategories::matches('iphones', ['328'], 'Apple MacBook', true), 'Apple laptops do not roll into iPhones');
techCheck(KREV_PA_Metacategories::matches('iphones', ['222'], 'Apple iPhone 12', false), 'legacy broad Google classification retains positive iPhone identity');
techCheck(!KREV_PA_Metacategories::matches('ai-tech', ['325'], 'ordinary desktop', false), 'AI-Tech requires explicit collection assignment');
techCheck(KREV_PA_Metacategories::matches('ai-tech', ['325'], '', false, ['ai-tech']), 'explicit AI-Tech assignment is independent of Google ID');
