if ($existingTarget && $existingTarget->post_title !== 'Synthetic Dell fixture') throw new RuntimeException('The reserved fixture slug is occupied by unrelated synthetic data.');
$target = $existingTarget ? wc_get_product($existingTarget->ID) : new WC_Product_Simple(); $target->set_name('Synthetic Dell fixture');
$target->set_slug('openclaw-plugin-ready-dell-optiplex-3020-i5-8gb-500gb-ubuntu-pc');
$target->set_category_ids([$root_id, (int) $desktop->term_id]); $target->set_status('publish'); $target->set_regular_price('43');
$target->set_manage_stock(true); $target->set_stock_quantity(1); $target->set_catalog_visibility('visible'); $target->save();
$target->update_meta_data('_wc_gla_google_product_category', 'original-google-value'); $target->save();
$beforeGoogle = KREV_Google_Category_Mapper::resolve_for_product($target)['id'];
delete_option('krev_metacategories_20261011_dell_done'); KREV_PA_Metacategories::setup(); $target = wc_get_product($target->get_id());
techCheck(in_array((int) $ai->term_id, $target->get_category_ids(), true), 'narrow migration assigns the requested Dell listing to AI-Tech');
techCheck(KREV_Google_Category_Mapper::resolve_for_product($target)['id'] === $beforeGoogle && $target->get_meta('_wc_gla_google_product_category') === 'original-google-value', 'Dell migration preserves both effective feed ID and existing Google plugin metadata');
techCheck(kr_metacategory_feed_category($target, wp_get_post_terms($target->get_id(), 'product_cat'))['id'] === $beforeGoogle, 'read-only storefront feed lookup agrees with Merchant Sync');
$chromecast = new WC_Product_Simple(); $chromecast->set_name('Synthetic Chromecast'); $chromecast->set_category_ids([$root_id, (int) $stream->term_id]); $chromecast->set_status('publish'); $chromecast->set_catalog_visibility('visible'); $chromecast->set_regular_price('15'); $chromecast->save();
$draft = new WC_Product_Simple(); $draft->set_name('Synthetic draft Chromecast'); $draft->set_category_ids([$root_id, (int) $stream->term_id]); $draft->set_status('draft'); $draft->save();
$hidden = new WC_Product_Simple(); $hidden->set_name('Synthetic hidden Chromecast'); $hidden->set_category_ids([$root_id, (int) $stream->term_id]); $hidden->set_status('publish'); $hidden->set_catalog_visibility('hidden'); $hidden->save();
$phoneTerm = get_term_by('slug', 'tech-google-267', 'product_cat');
$phone = new WC_Product_Simple(); $phone->set_name('Synthetic iPhone 11'); $phone->set_category_ids([$root_id, (int) $phoneTerm->term_id]); $phone->set_status('publish'); $phone->set_catalog_visibility('visible'); $phone->set_regular_price('25'); $phone->save();
$bluetoothTerm = get_term_by('slug', 'bluetooth-gadgets', 'product_cat');
techCheck($bluetoothTerm && KREV_PA_Metacategories::is_meta($bluetoothTerm->term_id) && (int) $bluetoothTerm->parent === $root_id, 'Bluetooth Gadgets is a native Tech collection after the existing-install upgrade');
techCheck(KREV_PA_Metacategories::matches('bluetooth-gadgets', ['5130'], '', false), 'Google Bluetooth transmitters roll up without a title clue');
techCheck(KREV_PA_Metacategories::matches('bluetooth-gadgets', ['249'], 'Bluetooth speaker', false), 'Bluetooth speakers roll up with positive evidence');
techCheck(!KREV_PA_Metacategories::matches('bluetooth-gadgets', ['249'], 'Wireless WiFi speaker', false), 'wireless alone does not mean Bluetooth');
techCheck(!KREV_PA_Metacategories::matches('bluetooth-gadgets', ['303'], 'Keyboard without Bluetooth', false), 'negative Bluetooth evidence is rejected');
techCheck(!KREV_PA_Metacategories::matches('bluetooth-gadgets', ['267'], 'Bluetooth iPhone', true), 'phones remain in their own collection rather than generic gadgets');
techCheck(KREV_PA_Metacategories::matches('bluetooth-gadgets', ['249'], 'Speaker', false, ['bluetooth-gadgets']), 'explicit seller collection selection is honored');
$speakerTerm = get_term_by('slug', 'tech-google-249', 'product_cat');
$btSpeaker = new WC_Product_Simple(); $btSpeaker->set_name('Synthetic Bluetooth speaker'); $btSpeaker->set_category_ids([$root_id, (int) $speakerTerm->term_id]); $btSpeaker->set_status('publish'); $btSpeaker->set_regular_price('12'); $btSpeaker->save();
$wiredSpeaker = new WC_Product_Simple(); $wiredSpeaker->set_name('Synthetic wired speaker'); $wiredSpeaker->set_category_ids([$root_id, (int) $speakerTerm->term_id]); $wiredSpeaker->set_status('publish'); $wiredSpeaker->set_regular_price('12'); $wiredSpeaker->save();
if (!taxonomy_exists('pa_connectivity')) register_taxonomy('pa_connectivity', ['product']);
$connectivityTerm = term_exists('Bluetooth', 'pa_connectivity') ?: wp_insert_term('Bluetooth', 'pa_connectivity');
$connectivityAttribute = new WC_Product_Attribute(); $connectivityAttribute->set_id(wc_attribute_taxonomy_id_by_name('connectivity')); $connectivityAttribute->set_name('pa_connectivity'); $connectivityAttribute->set_options([(int) $connectivityTerm['term_id']]); $connectivityAttribute->set_visible(true);
$attrSpeaker = new WC_Product_Simple(); $attrSpeaker->set_name('Synthetic portable speaker'); $attrSpeaker->set_category_ids([$root_id, (int) $speakerTerm->term_id]); $attrSpeaker->set_attributes([$connectivityAttribute]); $attrSpeaker->set_status('publish'); $attrSpeaker->set_regular_price('12'); $attrSpeaker->save();
$btIds = array_map(static fn($p) => $p->get_id(), kr_metacategory_products('bluetooth-gadgets'));
techCheck(in_array($btSpeaker->get_id(), $btIds, true) && !in_array($wiredSpeaker->get_id(), $btIds, true), 'Bluetooth inventory includes the evidenced speaker and excludes the wired speaker');
techCheck(in_array($attrSpeaker->get_id(), $btIds, true), 'connectivity attributes populate Bluetooth inventory without title keywords');
techCheck(KREV_Google_Category_Mapper::resolve_for_product($btSpeaker)['id'] === '249', 'Bluetooth browsing leaves the speaker Google feed category unchanged');
techCheck((bool) array_filter(kr_metacategory_children('bluetooth-gadgets'), static fn($row) => strpos($row['url'], 'kr_google_category=249') !== false), 'available Google speaker subtype appears under Bluetooth Gadgets');
