techCheck(in_array($chromecast->get_id(), $miniIds, true) && in_array($target->get_id(), $miniIds, true), 'Mini-Computers includes Chromecast and Dell desktop');
techCheck(!in_array($draft->get_id(), $miniIds, true) && !in_array($hidden->get_id(), $miniIds, true), 'unpublished and hidden products cannot populate groups or menus');
techCheck(!in_array($phone->get_id(), $miniIds, true) && in_array($phone->get_id(), array_map(static fn($p) => $p->get_id(), kr_metacategory_products('iphones')), true), 'Tech parent membership never assigns phones to the computer collections');
techCheck(!in_array($target->get_id(), array_map(static fn($p) => $p->get_id(), kr_metacategory_products('iphones')), true), 'Dell desktop does not populate the iPhones carousel');
$tree = kr_metacategory_navigation_tree([['label' => 'Models', 'url' => '/models', 'children' => []], ['label' => 'Shop All', 'url' => '/shop', 'children' => []], ['label' => 'Knife Type', 'children' => [['label' => 'Chef knife', 'url' => '/knife', 'children' => []]]]]);
techCheck(array_column($tree, 'label') === ['Models', 'Shop Categories', 'Shop All', 'Knife Type'], 'Shop Categories is placed between Models and Shop All');
$metaNames = array_column($tree[1]['children'], 'label');
techCheck(in_array('Home & Garden', $metaNames, true) && in_array('Bluetooth Gadgets', $metaNames, true) && in_array('AI-Tech', $metaNames, true) && in_array('Collectibles', $metaNames, true) && in_array('Pokémon Cards', $metaNames, true) && count($metaNames) === 15, 'all categories and metacategories appear in the new flyout branch');
techCheck($tree[1]['children'][0]['children'][0]['label'] === 'Chef knife', 'Kitchen Knives reuses the existing Knife Type submenu');
techCheck(strpos(do_shortcode('[kniferevive_header]'), 'Shop Categories') !== false, 'final header shortcode retains categories after the model-pages brand-menu rebuild');
$children = kr_metacategory_children('mini-computers');
techCheck((bool) array_filter($children, static fn($row) => strpos($row['url'], 'kr_google_category=5276') !== false), 'available Google streaming category appears beneath Mini-Computers');
techCheck(!(bool) array_filter($children, static fn($row) => strpos($row['url'], 'kr_google_category=328') !== false), 'empty unrelated Google laptop category is omitted beneath Mini-Computers');
$sections = kr_tech_metacategory_sections();
techCheck(strpos($sections, 'id="iphones"') !== false && strpos($sections, 'id="laptops"') !== false && strpos($sections, 'id="mini-computers"') !== false && strpos($sections, 'id="bluetooth-gadgets"') !== false, 'all four Tech sections and collection inventories render');
techCheck(strpos($sections, 'data-kr-tech-carousel') !== false && strpos($sections, 'collection theme') !== false, 'live product carousel and shared collection theme images are rendered');
$mainQuery = $wp_query; $originalMain = $wp_the_query;
