techCheck(in_array($chromecast->get_id(), $collectionQuery->posts, true), 'native collection archive shows Chromecast without the knife-only Shop filter');
$collectionQuery->query(['post_type' => 'product', 'kr_collection' => 'mini-computers', 'kr_google_category' => '5276', 'posts_per_page' => 100, 'fields' => 'ids']);
techCheck(in_array($chromecast->get_id(), $collectionQuery->posts, true) && !in_array($target->get_id(), $collectionQuery->posts, true), 'Google-filtered submenu archive retains streaming listings and excludes desktops');
techCheck(strpos(apply_filters('render_block_core/query-title', '<h1 class="wp-block-query-title">Shop Knives</h1>', []), 'Mini-Computers · Streaming &amp; Home Media Players') !== false, 'native collection archive title identifies the group and selected Google subtype');
$collectionQuery->query(['post_type' => 'product', 'kr_collection' => 'mini-computers', 'kr_google_category' => '999999999', 'fields' => 'ids']);
techCheck($collectionQuery->posts === [], 'empty Google-filtered collection never falls back to all products');
$collectionQuery->query(['post_type' => 'product', 'kr_collection' => 'bluetooth-gadgets', 'kr_google_category' => '249', 'posts_per_page' => 100, 'fields' => 'ids']);
